import style from "./PartnersPage.module.scss";
import {RunningText} from "../_common/RunningText/RunningText";
import {agents, partners} from "./data";


export const PartnersPage = () => {
    return (
        <div className={style.partnersPage}>

            <RunningText/>
            <RunningText top={false}/>

            <div className={style.card}>

                <div className={style.cardHeader}>

                    <h2 className={style.title}>
                        Partners
                    </h2>

                    <a href="#"
                       target="_blank"
                       rel="noreferrer nofollow noopener"
                    >
                        Apply
                    </a>

                </div>

                <div className={style.partners}>
                    <div className={style.inner}>
                        {
                            partners.map(({src, href, label}, key) => (
                                <a key={key}
                                   href={href}
                                   target="_blank"
                                   rel="noreferrer nofollow noopener"
                                   className={style.partner}
                                >
                                    <img src={src} alt=""/>
                                    <p>{label}</p>
                                </a>
                            ))
                        }
                    </div>
                </div>


                <h3 className={style.subtitle}>
                    Agents
                </h3>

                <div className={style.partners}>
                    <div className={style.inner}>
                        {
                            agents.map(({src, href, label}, key) => (
                                <a key={key}
                                   href={href}
                                   target="_blank"
                                   rel="noreferrer nofollow noopener"
                                   className={style.partner}
                                >
                                    <img src={src} alt=""/>
                                    <p>{label}</p>
                                </a>
                            ))
                        }
                    </div>
                </div>

            </div>


        </div>
    )
}