import {action, makeObservable, observable} from "mobx";

export class AppStore {
    showedPreloader = false

    constructor() {
        makeObservable(this,
            {
                showedPreloader: observable,

                setShowedPreloader: action.bound,
            }
        )
    }

    setShowedPreloader(showedPreloader: boolean) {
        this.showedPreloader = showedPreloader;
    }

}