import style from "./HomePage.module.scss"
import {observer} from "mobx-react-lite";
import {useStore} from "../../store/rootStore";
import {useEffect, useRef} from "react";
import gsap from "gsap";
import {useGSAP} from "@gsap/react";
import clsx from "clsx";
import head from "../../assets/png/head.png";
import {useTime} from 'react-timer-hook';
import {Link} from "react-router";
import src_link_0 from "../../assets/png/home_links_0.png";
import src_link_1 from "../../assets/png/home_links_1.png";
import src_link_2 from "../../assets/png/home_links_2.png";
import src_link_3 from "../../assets/png/home_links_3.png";
import {RunningText} from "../_common/RunningText/RunningText";

export const HomePage = observer(() => {
    const {appStore: {showedPreloader, setShowedPreloader}} = useStore()

    const {
        minutes,
        hours,
    } = useTime({
        //format: "12-hour"
    });

    const appRef = useRef<HTMLDivElement>(null!);
    const tlRef = useRef<gsap.core.Timeline>(null!);

    useEffect(() => {
        const timer = setTimeout(() => {
            setShowedPreloader(true);
        }, 2000)
        return () => clearTimeout(timer);
    }, []);

    useGSAP(() => {
        tlRef.current = gsap.timeline()
            .to(".preloader", {
                opacity: 0,
                duration: 0.5,
            })
            .set(".preloader", {
                display: "none"
            })
        tlRef.current.pause();




    }, {scope: appRef, dependencies: [showedPreloader]})

    useGSAP(() => {
        //gsap.fromTo(".head", {opacity: 0}, {opacity: 1, duration: 0.5, })
        gsap.to(".head", {opacity: 1, duration: 2, delay: 0.5, ease: "none"})
    }, {scope: appRef})

    useEffect(() => {
        if (showedPreloader) {
            tlRef.current.play()
        }
    }, [showedPreloader]);

    return (
        <div className={style.homePage}
             ref={appRef}
        >
            <RunningText/>
            <RunningText top={false}/>

            <div className={style.top}>
                <p className={style.time}>
                    {hours < 10 ? `0${hours}` : hours}:{minutes < 10 ? `0${minutes}` : minutes}
                </p>
                <h1 className={style.title}>
                    T<span>|</span>OS
                </h1>
            </div>

            <div className={style.bottom}>
                <nav className={style.links}>
                    {
                        [
                            {
                                label: "DAO",
                                to: "/dao",
                                src: src_link_0,
                            },
                            {
                                label: "Brands",
                                to: "/brands",
                                src: src_link_1,
                            },
                            {
                                label: "Partners",
                                to: "/partners",
                                src: src_link_2,
                            },
                            {
                                label: "Profile",
                                to: "/profile",
                                src: src_link_3,
                            },
                        ].map(({label, src, to}, key) => (
                            <Link key={key}
                                  to={to}
                                  className={style.link}
                            >
                                <img src={src} alt=""/>
                                <p>{label}</p>
                            </Link>
                        ))
                    }
                </nav>

                <nav className={style.socialLinks}>
                    {
                        [
                            {
                                label: "Twitter",
                                href: "#",
                            },
                            {
                                label: " Instagram",
                                href: "#",
                            },
                            {
                                label: "Linkdln",
                                href: "#",
                            },
                            {
                                label: "Profile",
                                href: "#",
                            },
                        ].map(({label, href}, key) => (
                            <a key={key}
                               href={href}
                               className={style.socialLink}
                               target="_blank"
                               rel="noreferrer nofollow noopener"
                            >
                                <p>{label}</p>
                            </a>
                        ))
                    }
                </nav>
            </div>

            <div className={clsx(style.preloader, "preloader")}>
                <img src={head} alt="" className="head"/>
            </div>
        </div>
    )
})