import style from "./RunningText.module.scss"
import {RunningStringItem} from "../RunningStringItem/RunningStringItem";
import {FC} from "react";
import clsx from "clsx";
import head_small from "../../../assets/png/head_small.png"
import {svgIcons} from "../../../assets/svgIcons";

interface IRunningText {
    top?: boolean
}

export const RunningText: FC<IRunningText> = ({top = true}) => {
    return (
        <div className={clsx({
            [style.runningText]: true,
            [style.runningText_bottom]: !top,
        })}>
            <RunningStringItem forward={false}
                               duration={60}
                               count={5}
                               item={(
                                   <div className={style.item}>
                                       <img src={head_small} alt=""/>
                                       <p>T</p>
                                       <p>(OPERATING SYSTEM)</p>
                                       {svgIcons.arrow_up_right}
                                       <p>THE OPERATING SYSTEM FOR AI AGENTS</p>
                                   </div>
                               )}

            />
        </div>


    )
}